        { "table": "WindowsEvent", "mode": "Fixed table", "verified": true, "source_ids": ["src-la-table-windowsevent"], "notes": "Events collected through Windows Event Forwarding and sent by the agent (Microsoft Sentinel Windows Forwarded Events connector)." }
